<?php $labels=['draft'=>'Rascunho','pending'=>'Pendente','under_review'=>'Em análise','approved'=>'Aprovado','rejected'=>'Correção','suspended'=>'Suspenso','cancelled'=>'Cancelado']; ?>
<div class="dashboard-heading"><div><span class="eyebrow">OPERAÇÃO B2B</span><h2>Cadastros atacadistas.</h2><p>Analise empresas, documentos e histórico sem criar usuários duplicados.</p></div><span class="date-chip"><?=array_sum(array_map('intval',$counts))?> cadastros</span></div>
<nav class="filter-pills"><a class="<?=$filterStatus===''?'is-active':''?>" href="<?=e(url('/admin/atacadistas'))?>">Todos</a><?php foreach(['pending','under_review','approved','rejected','suspended'] as $key):?><a class="<?=$filterStatus===$key?'is-active':''?>" href="<?=e(url('/admin/atacadistas?status='.$key))?>"><?=e($labels[$key])?> <span><?=(int)($counts[$key]??0)?></span></a><?php endforeach;?></nav>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Empresa</th><th>CNPJ</th><th>Responsável</th><th>Envio</th><th>Status</th><th>Ação</th></tr></thead><tbody><?php if(!$accounts):?><tr><td colspan="6"><div class="empty-state"><h3>Nenhum cadastro nesta fila</h3><p>Novas solicitações aparecerão aqui.</p></div></td></tr><?php endif;?><?php foreach($accounts as $account):?><tr><td><strong><?=e($account['trade_name']?:$account['legal_name'])?></strong><small class="table-subtitle"><?=e($account['customer_email'])?></small></td><td><span data-format-cnpj><?=e($account['cnpj'])?></span></td><td><?=e($account['responsible_name']?:'—')?></td><td><?= $account['submitted_at']?date('d/m/Y',strtotime($account['submitted_at'])):'—' ?></td><td><?php $status=$account['status'];require dirname(__DIR__,2).'/components/dashboard/status-badge.php';?></td><td><a class="table-link" href="<?=e(url('/admin/atacadistas/'.$account['id']))?>">Analisar →</a></td></tr><?php endforeach;?></tbody></table></div></section>
